const viewer = (window.viewer = new Cesium.Viewer('cesiumContainer', {
  baseLayer: new Cesium.ImageryLayer(
    new Cesium.OpenStreetMapImageryProvider({ url: 'https://tile.openstreetmap.org/', maximumLevel: 18 })
  ),
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false,
}));

viewer.scene.globe.enableLighting = false;

const start = Cesium.JulianDate.fromIso8601('2026-05-20T12:00:00Z');
const stop  = Cesium.JulianDate.addSeconds(start, 60, new Cesium.JulianDate());

viewer.clock.startTime   = start.clone();
viewer.clock.stopTime    = stop.clone();
viewer.clock.currentTime = start.clone();
viewer.clock.multiplier  = 1;
viewer.clock.clockRange  = Cesium.ClockRange.LOOP_STOP;
viewer.clock.shouldAnimate = true;

const position = new Cesium.SampledPositionProperty();
position.setInterpolationOptions({
  interpolationAlgorithm: Cesium.HermitePolynomialApproximation,
  interpolationDegree: 2,
});
position.forwardExtrapolationType = Cesium.ExtrapolationType.HOLD;
position.backwardExtrapolationType = Cesium.ExtrapolationType.HOLD;

const samples = [
  { t:  0, lon: -73.7781,  lat: 40.6413, alt:  9000 }, // JFK
  { t: 20, lon: -98.0,     lat: 39.0,    alt: 11000 }, // Kansas
  { t: 40, lon: -104.9903, lat: 39.7392, alt: 11000 }, // Denver
  { t: 60, lon: -118.4085, lat: 33.9416, alt:  9000 }, // LAX
];

for (const s of samples) {
  position.addSample(
    Cesium.JulianDate.addSeconds(start, s.t, new Cesium.JulianDate()),
    Cesium.Cartesian3.fromDegrees(s.lon, s.lat, s.alt)
  );
}

const entity = viewer.entities.add({
  availability: new Cesium.TimeIntervalCollection([
    new Cesium.TimeInterval({ start, stop }),
  ]),
  position,
  orientation: new Cesium.VelocityOrientationProperty(position),
  point: {
    pixelSize: 14,
    color: Cesium.Color.CYAN,
    outlineColor: Cesium.Color.WHITE,
    outlineWidth: 2,
  },
  path: {
    width: 3,
    leadTime: 60,
    trailTime: 60,
    material: Cesium.Color.YELLOW,
    resolution: 1,
  },
});

// Advance currentTime to start + 30s so entity is mid-flight near Denver
viewer.clock.currentTime = Cesium.JulianDate.addSeconds(start, 30, new Cesium.JulianDate());

// Frame camera on the mid-point position (roughly between Kansas and Denver)
viewer.camera.setView({
  destination: Cesium.Cartesian3.fromDegrees(-101.5, 41.5, 4500000),
  orientation: {
    heading: Cesium.Math.toRadians(0),
    pitch:   Cesium.Math.toRadians(-55),
    roll:    0,
  },
});
